{
    if (bool(mpFillBitmapItem))
        restoreFillBitmap();
    ImpInsertPage(nPageNum);
    if (m_pUndoGroup!=nullptr)
    {
        // recover master page relationships
        m_pUndoGroup->Undo();
    }
}
